 it('generates bilingual exact signed schedules and receipt/statement evidence from completed database workflows',async()=>{
  const directory=resolve(__dirname,'../../../output/pdf/final-delivery');mkdirSync(directory,{recursive:true});
  const cases=[{name:'plan-a-contract',app:student,rows:8,total:6400000n},{name:'plan-b-contract',app:completedJourney,rows:8,total:6400000n},{name:'cash-contract',app:cashStudent,rows:2,total:5400000n}];
  const documents:any[]=[];for(const fixture of cases){const value:any=await av8.statement(admin,BigInt(fixture.app.id),'contract');expect(value.rows).toHaveLength(fixture.rows);expect(value.rows.reduce((n:bigint,r:any)=>n+BigInt(r.amount.replace('.','')),0n)).toBe(fixture.total);expect(value.rows.filter((r:any)=>r.milestone!=='VISA').every((r:any)=>r.dueDate)).toBe(true);documents.push({name:fixture.name,applicationId:fixture.app.id,value});}
  documents.push({name:'partial-student-statement',applicationId:student.id,value:await av8.statement(admin,BigInt(student.id),'student')},{name:'cash-academy-statement',applicationId:cashStudent.id,value:await av8.statement(admin,BigInt(cashStudent.id),'academy')},{name:'bank-fee-receipt',fundId:feeReceiptFundId,value:await fin.receiptDocument(admin,BigInt(feeReceiptFundId))});
  for(const fixture of documents){writeFileSync(resolve(directory,fixture.name+'.source.json'),JSON.stringify(fixture,null,2));for(const language of ['en','ar'] as const){const doc=statementPdf(fixture.value,language);const bytes=await new Promise<Buffer>((done,reject)=>{const chunks:Buffer[]=[];doc.on('data',chunk=>chunks.push(chunk));doc.on('end',()=>done(Buffer.concat(chunks)));doc.on('error',reject);doc.end();});expect(bytes.subarray(0,5).toString()).toBe('%PDF-');writeFileSync(resolve(directory,`${fixture.name}-${language}.pdf`),bytes);}}
 });
